const WorkflowRandomCohortStepBranchSchema: z.ZodType<WorkflowRandomCohortStepBranchType> = z
  .lazy(() =>
    z
      .object({
        name: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The name of the cohort branch.',
            example: 'Control',
            'x-struct': null,
            'x-validate': null,
          }),
        percentage: z
          .string()
          .openapi({
            description:
              'The percentage of recipients to assign to this cohort. Must be between 0 and 100 with at most 1 decimal place. All branch percentages must sum to 100. Sent as a number in requests; returned as a decimal string in responses (e.g. "50", "33.3").',
            example: '50',
            'x-struct': null,
            'x-validate': null,
          }),
        steps: z
          .array(WorkflowStepSchema)
          .exactOptional()
          .openapi({
            description:
              'A list of steps that will be executed for recipients assigned to this cohort.',
            'x-struct': null,
            'x-validate': null,
          }),
        terminates: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'If the workflow should halt at the end of the branch. Defaults to false if not provided.',
            example: false,
            'x-struct': null,
            'x-validate': null,
          }),
      })
      .openapi({
        description: 'A cohort branch in an experiment step.',
        example: { name: 'Control', percentage: '50', steps: [], terminates: false },
        required: ['percentage'],
        title: 'WorkflowRandomCohortStepBranch',
        'x-struct': 'Elixir.ControlWeb.V1.Specs.WorkflowRandomCohortStep.CohortBranch',
        'x-validate': null,
      }),
  )
  .openapi('WorkflowRandomCohortStepBranch')

type WorkflowRandomCohortStepType = {
  cohort_branches: z.infer<typeof WorkflowRandomCohortStepBranchSchema>[]
  cohort_key?: string | null
  description?: string | null
  name?: string | null
  ref: string
  type: 'random_cohort'
}

